import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Moltiplicazione fra numeri naturali","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/b_aritmetica-e-numeri/ba/bae.md","filePath":"lezioni/b_aritmetica-e-numeri/ba/bae.md"}`),a={name:`lezioni/b_aritmetica-e-numeri/ba/bae.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="moltiplicazione-fra-numeri-naturali" tabindex="-1">Moltiplicazione fra numeri naturali <a class="header-anchor" href="#moltiplicazione-fra-numeri-naturali" aria-label="Permalink to “Moltiplicazione fra numeri naturali”">​</a></h1><p>D&#39;ora in avanti useremo indifferentemente i termini prodotto e moltiplicazione anche se il prodotto indica il risultato mentre la moltiplicazione indica l&#39;operazione.</p><p class="text-red-darken-1">[<strong>Nei numeri naturali dovremmo indicare l&#39;operazione di moltiplicazione mediante il simbolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>x</mtext></mrow><annotation encoding="application/x-tex">\\text{x}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord text"><span class="mord">x</span></span></span></span></span>, ma io sono <a href="./bae1.html">contrario</a> all&#39;uso di questo simbolo e preferisco usare il simbolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>⋅</mo></mrow><annotation encoding="application/x-tex">\\cdot</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4445em;"></span><span class="mord">⋅</span></span></span></span></strong>]</p><p>Disegno su una semiretta l&#39;insieme dei numeri naturali:</p><p>Se voglio fare</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="blue"><mn>3</mn></mstyle><mo>⋅</mo><mstyle mathcolor="green"><mn>2</mn></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{3} \\cdot \\textcolor{green}{2} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:blue;">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:green;">2</span></span></span></span></span></p><p>disegno a partire da <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> un segmento lungo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span>.</p><p>Per moltiplicare ripeto il segmento <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> per due volte ed ottengo che il risultato termina in <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>6</mn></mrow><annotation encoding="application/x-tex">6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span>.</p><p>quindi</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="blue"><mn>3</mn></mstyle><mo>⋅</mo><mstyle mathcolor="blue"><mn>2</mn></mstyle><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">\\textcolor{blue}{3} \\cdot \\textcolor{blue}{2} = 6 </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:blue;">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:blue;">2</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span></span></p><p>C&#39;è subito da dire che facendo il prodotto fra numeri naturali mi muovo sempre verso destra e, a destra, i numeri sono infiniti; quindi potrò sempre fare la moltiplicazione, cioè la moltiplicazione fra numeri naturali è un&#39;operazione interna e l&#39;insieme <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi></mrow><annotation encoding="application/x-tex">N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> è chiuso rispetto alla moltiplicazione.</p><p>Fra tutti i numeri naturali ne esiste uno particolare: l&#39;uno; L&#39;uno ha la proprietà di non cambiare niente infatti preso un numero qualunque</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mn>1</mn><mo>⋅</mo><mtext>numero</mtext><mo>=</mo><mtext>numero</mtext><mo>⋅</mo><mn>1</mn><mo>=</mo><mtext>numero</mtext></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{1 \\cdot \\text{numero} = \\text{numero} \\cdot 1 = \\text{numero}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin" style="color:red;">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">numero</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4445em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">numero</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin" style="color:red;">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">numero</span></span></span></span></span></span></p><p>Si esprime questo fatto dicendo che:</p><p class="text-red-darken-1">[<strong>uno è l&#39;elemento neutro per la moltiplicazione</strong>]</p><blockquote><p>questa proprietà sarà sempre valida per tutti i numeri: naturali, interi, razionali, reali, complessi</p></blockquote><p>Anche lo zero è speciale per la moltiplicazione: Lo zero ha la proprietà di &quot;assorbire&quot; tutti i numeri con cui è moltiplicato facendoli diventare zero</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mn>0</mn><mo>⋅</mo><mtext>numero</mtext><mo>=</mo><mtext>numero</mtext><mo>⋅</mo><mn>0</mn><mo>=</mo><mn>0</mn></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{0 \\cdot \\text{numero} = \\text{numero} \\cdot 0 = 0} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin" style="color:red;">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">numero</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4445em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">numero</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin" style="color:red;">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">0</span></span></span></span></span></p><p>Si esprime questo fatto dicendo che:</p><p class="text-red-darken-1">[<strong>zero è l&#39;elemento assorbente per la moltiplicazione</strong>]</p><blockquote><p>questa proprietà sarà sempre valida per tutti i numeri: naturali, interi, razionali, reali, complessi</p></blockquote><p>Da questa proprietà deriverà la <a href="./bae2.html">legge di annullamento del prodotto</a></p>`,22)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};